assert(world&&evidence&&binary);fs.mkdirSync(evidence,{recursive:true,mode:0o700});
const origin='https://127.0.0.1:'+fs.readFileSync(path.join(world,'mux-port'),'utf8').trim();
const nativeURLs=Object.fromEntries(['alice','bob','dana'].map(n=>[n,fs.readFileSync(path.join(world,n+'-ui'),'utf8').match(/http:\/\/127\.0\.0\.1:\d+\/\?t=[a-f0-9]+/)[0]]));
const allowed=new Set([origin,'https://127.0.0.1:'+fs.readFileSync(path.join(world,'other-port'),'utf8').trim(),...Object.values(nativeURLs).map(s=>new URL(s).origin)]),errors=[],outside=[],shots=[],checks=[],actions=[];
const cli=(n,...a)=>execFileSync(binary,['--home',path.join(world,n),...a],{encoding:'utf8',env:process.env});
const cert=new X509Certificate(fs.readFileSync(path.join(world,'cert.pem'))),spki=createHash('sha256').update(cert.publicKey.export({type:'spki',format:'der'})).digest('base64');
